/* Deriva horizontal lenta das nuvens — cada camada numa velocidade
   diferente pra dar sensação de profundidade (fundo mais devagar,
   frente mais rápido), como se estivessem passando pelo lado. */

@keyframes cloud-drift {
  0%,
  100% {
    transform: translateX(0);
  }
  50% {
    transform: translateX(var(--cloud-drift-x, 3%));
  }
}

@keyframes cloud-drift-flip {
  0%,
  100% {
    transform: scaleX(-1) translateX(0);
  }
  50% {
    transform: scaleX(-1) translateX(var(--cloud-drift-x, 3%));
  }
}

.cloud-drift {
  animation: cloud-drift var(--cloud-drift-duration, 30s) ease-in-out infinite;
}

.cloud-drift-flip {
  animation: cloud-drift-flip var(--cloud-drift-duration, 30s) ease-in-out infinite;
}

/* Borboletas atravessando a largura inteira da página, da esquerda pra
   direita, com fade nas pontas pra esconder o corte do loop. */
@keyframes birds-cross {
  0% {
    transform: translateX(-100%);
    opacity: 0;
  }
  6% {
    opacity: 1;
  }
  94% {
    opacity: 1;
  }
