import { useLayoutEffect, useRef, useState, type FC, type PointerEvent } from 'react'
import gsap from 'gsap'
import ScrollTrigger from 'gsap/ScrollTrigger'

gsap.registerPlugin(ScrollTrigger)

const SUNSET_IMAGE_URL =
  'https://res.cloudinary.com/dwmrunhxa/image/upload/q_auto,f_auto,w_2200/v1788461241/Sunset_view_with_infinity_pool_202609031547_zyfond.jpg'

export const TwilightSection: FC = () => {
  const sectionRef = useRef<HTMLElement>(null)
  const pinRef = useRef<HTMLDivElement>(null)
  const bgImgDarkRef = useRef<HTMLImageElement>(null)
  const bgImgLightRef = useRef<HTMLImageElement>(null)
  const phase1Ref = useRef<HTMLDivElement>(null)
  const phase2Ref = useRef<HTMLDivElement>(null)
  const phase3Ref = useRef<HTMLDivElement>(null)

  const [mousePos, setMousePos] = useState<{ x: number; y: number; hasMoved: boolean }>({
    x: 50,
    y: 50,
    hasMoved: false,
  })

  // Rastreia a posição do mouse na tela para o efeito de lanterna/spotlight
  const handlePointerMove = (e: PointerEvent<HTMLDivElement>) => {
    const rect = e.currentTarget.getBoundingClientRect()
    const x = e.clientX - rect.left
    const y = e.clientY - rect.top
    setMousePos({ x, y, hasMoved: true })
  }

  useLayoutEffect(() => {
    const ctx = gsap.context(() => {
      const tl = gsap.timeline({
        scrollTrigger: {
          trigger: sectionRef.current,
          start: 'top top',
          end: 'bottom bottom',
          pin: pinRef.current,
          pinSpacing: true,
          scrub: 0.7,
        },
      })

      // Zoom sutil contínuo em ambas as camadas de imagem
      tl.fromTo(
        [bgImgDarkRef.current, bgImgLightRef.current],
        { scale: 1.12 },
        { scale: 1.0, ease: 'none', duration: 3 },
        0,
      )

      // Fase 1: Canto Superior Esquerdo — Começa visível e sai
      tl.fromTo(
        phase1Ref.current,
        { autoAlpha: 1, x: 0, y: 0 },
        { autoAlpha: 0, x: -30, y: -15, ease: 'power2.inOut', duration: 0.6 },
        0.4,
      )

      // Fase 2: Canto Inferior Direito — Surge e sai
      .fromTo(
        phase2Ref.current,
        { autoAlpha: 0, x: 30, y: 25 },
        { autoAlpha: 1, x: 0, y: 0, ease: 'power2.out', duration: 0.6 },
        0.9,
      )
      .to(
        phase2Ref.current,
        { autoAlpha: 0, x: 20, y: -20, ease: 'power2.in', duration: 0.6 },
        1.7,
      )

      // Fase 3: Centro Minimalista — Surge e fixa no clímax
      .fromTo(
        phase3Ref.current,
        { autoAlpha: 0, y: 25, scale: 0.96 },
        { autoAlpha: 1, y: 0, scale: 1, ease: 'power2.out', duration: 0.65 },
        2.2,
      )
      .to({}, { duration: 0.4 })
    }, sectionRef)

    return () => ctx.revert()
  }, [])

  return (
    <section
      ref={sectionRef}
      id="crepusculo"
      className="relative h-[300vh] w-full bg-ink text-paper select-none"
    >
      <div
        ref={pinRef}
        onPointerMove={handlePointerMove}
        className="relative flex h-screen w-full overflow-hidden bg-ink cursor-crosshair"
      >
        {/* Camada 1: Imagem de Base (Escura, levemente aparente com filtro preto) */}
        <div className="absolute inset-0 h-full w-full overflow-hidden">
          <img
            ref={bgImgDarkRef}
            src={SUNSET_IMAGE_URL}
            alt="Pôr do sol cinematográfico"
            className="h-full w-full object-cover object-center opacity-30 brightness-[0.65] contrast-[1.1] will-change-transform"
          />
          <div className="absolute inset-0 bg-gradient-to-t from-black/85 via-black/40 to-black/60" />
        </div>

        {/* Camada 2: Imagem Iluminada Revelada pelo Movimento do Mouse (Spotlight / Flashlight) */}
        <div
          className="pointer-events-none absolute inset-0 h-full w-full overflow-hidden transition-opacity duration-700"
          style={{
            opacity: mousePos.hasMoved ? 1 : 0,
            WebkitMaskImage: mousePos.hasMoved
              ? `radial-gradient(circle 340px at ${mousePos.x}px ${mousePos.y}px, black 0%, rgba(0,0,0,0.5) 55%, transparent 100%)`
              : 'none',
            maskImage: mousePos.hasMoved
              ? `radial-gradient(circle 340px at ${mousePos.x}px ${mousePos.y}px, black 0%, rgba(0,0,0,0.5) 55%, transparent 100%)`
              : 'none',
          }}
        >
          <img
            ref={bgImgLightRef}
            src={SUNSET_IMAGE_URL}
            alt="Pôr do sol iluminado"
            className="h-full w-full object-cover object-center brightness-[1.05] contrast-[1.08] will-change-transform"
          />
          <div className="absolute inset-0 bg-gradient-to-t from-black/50 via-transparent to-black/30" />
        </div>

        {/* Sutil brilho de cursor */}
        {mousePos.hasMoved && (
          <div
            className="pointer-events-none absolute h-2 w-2 -translate-x-1/2 -translate-y-1/2 rounded-full bg-[#cbb592]/60 blur-xs"
            style={{ left: mousePos.x, top: mousePos.y }}
          />
        )}

        {/* FASE 1: Canto Superior Esquerdo (Minimalista) */}
        <div
          ref={phase1Ref}
          className="pointer-events-none absolute top-14 sm:top-20 md:top-24 left-6 sm:left-12 md:left-20 z-20 flex flex-col items-start text-left max-w-xs sm:max-w-md"
        >
          <span className="font-sans text-[9px] sm:text-[10px] uppercase tracking-[0.28em] text-[#cbb592] font-semibold mb-2">
            05 — Crepúsculo
          </span>
          <h2 className="font-display text-2xl sm:text-3xl md:text-4xl lg:text-[2.75rem] uppercase tracking-[-0.015em] text-paper leading-[1.05]">
            "O tempo aqui não tem pressa..."
          </h2>
          <div className="flex flex-col gap-[2.5px] w-10 my-3">
            <div className="h-[1px] w-full bg-[#cbb592]/60" />
            <div className="h-[1px] w-full bg-[#cbb592]/60" />
          </div>
          <p className="font-sans text-[9px] sm:text-[9.5px] uppercase tracking-[0.04em] leading-[1.7] text-paper/60 font-medium">
            Entre o silêncio da brisa e o horizonte do oceano.
          </p>
        </div>

        {/* FASE 2: Canto Inferior Direito (Minimalista) */}
        <div
          ref={phase2Ref}
          className="pointer-events-none absolute bottom-14 sm:bottom-20 md:bottom-24 right-6 sm:right-12 md:right-20 z-20 flex flex-col items-end text-right max-w-xs sm:max-w-md opacity-0"
        >
          <span className="font-sans text-[9px] sm:text-[9.5px] uppercase tracking-[0.26em] text-[#cbb592] font-semibold mb-2">
            A Luz Dourada
          </span>
          <h2 className="font-display text-2xl sm:text-3xl md:text-4xl lg:text-[2.75rem] uppercase tracking-[-0.015em] text-paper leading-[1.05]">
            "...Ele se torna infinito."
          </h2>
          <span className="font-script text-2xl sm:text-3xl md:text-4xl text-[#cbb592] mt-1 -rotate-1 inline-block">
            Sob o céu do Mediterrâneo
          </span>
          <div className="flex flex-col gap-[2.5px] w-10 my-3 items-end">
            <div className="h-[1px] w-full bg-[#cbb592]/60" />
            <div className="h-[1px] w-full bg-[#cbb592]/60" />
          </div>
        </div>

        {/* FASE 3: Centro Minimalista com Botão de Ação VIP */}
        <div
          ref={phase3Ref}
          className="pointer-events-none absolute inset-0 z-20 flex flex-col items-center justify-center text-center px-6 opacity-0"
        >
          <span className="font-sans text-[9px] sm:text-[10px] uppercase tracking-[0.3em] text-[#cbb592] font-semibold mb-2">
            Exclusividade Atemporal
          </span>
          <h2 className="font-display text-3xl sm:text-4xl md:text-5xl lg:text-6xl uppercase tracking-[0.06em] text-paper leading-tight">
            Alba Residência
          </h2>
          <span className="font-sans text-[9px] sm:text-[10px] uppercase tracking-[0.22em] text-paper/60 mt-1 mb-7">
            Costa del Sol · Refúgio de Poder
          </span>

          {/* Botão com clique habilitado */}
          <a
            href="#contato"
            className="pointer-events-auto inline-flex items-center justify-center gap-2.5 rounded-full bg-[#cbb592] px-7 py-3 font-sans text-[9.5px] sm:text-[10px] uppercase tracking-[0.22em] text-[#16120e] font-semibold shadow-xl transition-all duration-300 hover:bg-[#dfcca8] hover:scale-105 active:scale-95 cursor-pointer"
          >
            <span>Agendar Experiência Privada</span>
            <svg
              className="h-3 w-3 translate-x-0.5"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <line x1="5" y1="12" x2="19" y2="12" />
              <polyline points="12 5 19 12 12 19" />
            </svg>
          </a>
        </div>

        {/* Rodapé minimalista */}
        <footer className="pointer-events-none absolute inset-x-0 bottom-0 z-30 flex items-center justify-between p-6 sm:p-8 text-paper/30">
          <span className="font-sans text-[8.5px] uppercase tracking-[0.2em]">
