  const videoRef = useRef(null);
  const heroFooterRef = useRef(null);

  useLayoutEffect(() => {
    const ctx = gsap.context(() => {
      /* ================================================================
         ESTADO INICIAL — trava tudo antes do primeiro frame pintar.
         A máscara do título é um clip-path temporário com o topo
         estendido (-50%), pra nunca cortar o topo das capitulares do
         display font; só a linha de baixo é que segura o texto.
         ================================================================ */
      // `transition: none` é obrigatório aqui: o botão BAG usa `transition-all`
      // do Tailwind, então sem isso o opacity 0 vira uma transição CSS de 150ms
      // e o botão pisca na tela antes de ser travado.
      gsap.set('[data-hero="header-item"]', { opacity: 0, y: -14, transition: 'none' });
      gsap.set(titleWrapRef.current, { clipPath: 'inset(-50% 0% 0% 0%)' });
      gsap.set(titleRef.current, { yPercent: 115 });
      gsap.set(videoRef.current, { scale: 1.18 });
      gsap.set('[data-hero="footer-item"]', { opacity: 0, y: 10 });

      // Wipe do vídeo controlado por um proxy numérico: o browser normaliza
      // `inset()` (colapsa valores iguais), e o GSAP só interpola string
      // complexa quando a contagem de números bate nas duas pontas.
      const wipe = { inset: 46 };
      const applyWipe = () =>
        gsap.set(videoWrapRef.current, { clipPath: `inset(${wipe.inset}% 0%)` });

      applyWipe();

      /* ================================================================
         ENTRADA DA HERO — cortina editorial.
         header -> título sobe pela máscara -> vídeo abre em wipe
         horizontal com push-in -> rodapé assenta.
         ================================================================ */
      const intro = gsap.timeline({ delay: 0.15 });

      intro
        .to('[data-hero="header-item"]', {
          opacity: 1,
          y: 0,
          duration: 1.1,
          ease: 'expo.out',
          stagger: 0.06,
          // Devolve o transition ao CSS: o hover e o active:scale-95 do BAG voltam a valer.
          onComplete: () =>
            gsap.set('[data-hero="header-item"]', { clearProps: 'transition,transform' }),
        }, 0)
        .to(titleRef.current, {
          yPercent: 0,
          duration: 1.5,
          ease: 'expo.out',
          // Máscara e transform saem de cena: o título volta 100% ao CSS original.
          onComplete: () => {
            gsap.set(titleWrapRef.current, { clearProps: 'clipPath' });
            gsap.set(titleRef.current, { clearProps: 'transform' });
          },
        }, 0.25)
        .to(wipe, {
          inset: 0,
          duration: 1.6,
          ease: 'expo.inOut',
          onUpdate: applyWipe,
          // Sem clip residual: o vídeo volta ao overflow-hidden do CSS.
          onComplete: () => gsap.set(videoWrapRef.current, { clearProps: 'clipPath' }),
        }, 0.55)
        .to(videoRef.current, {
          scale: 1,
          duration: 2.2,
          ease: 'expo.out',
          onComplete: () => gsap.set(videoRef.current, { clearProps: 'transform' }),
        }, 0.55)
        .to('[data-hero="footer-item"]', {
          opacity: 1,
          y: 0,
          duration: 1,
          ease: 'expo.out',
          stagger: 0.1,
        }, 1.15);

      /* ================================================================
         SAÍDA DA HERO — parallax de dissolução, atrelado ao scroll.
         Alvos separados da entrada de propósito: a entrada anima os
         elementos internos (h1, video), a saída anima os containers.
