      id="shop"
      ref={sectionRef}
      data-cards-done={isAllCardsDone}
      className="w-full bg-[#f8f8f9] text-slate-900 py-16 sm:py-24 px-4 sm:px-10 select-none overflow-hidden relative border-t border-slate-200/80"
    >
