            <span className="group-hover:translate-x-1 transition-transform">→</span>
          </a>
        </div>

        {/* 2. GRID DE 3 CARDS COM ENTRADA ACELERADA */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8 sm:gap-10 items-end relative">

