              <button
                type="button"
                onClick={() => setOpenIndex(openIndex === i ? null : i)}
                aria-expanded={openIndex === i}
                className="w-full flex items-baseline gap-4 sm:gap-10 py-7 sm:py-9 text-left group cursor-pointer"
              >
