        .to(frame, { scale: 1, duration: 2.6, ease: 'expo.out' }, 0)
        .to('[data-anim="nav-item"]', { opacity: 1, y: 0, duration: 0.9, stagger: 0.08 }, 0.9)
        .to('[data-anim="intro-olho"]', { opacity: 1, y: 0, duration: 0.8 }, 1.05)
        .to('[data-anim="intro-linha"]', {
