          stagger: 0.09,
        }, 1.2)
        .to('[data-anim="intro-sub"]', { opacity: 1, y: 0, duration: 0.9 }, 1.75)
        .to('[data-anim="intro-cta"]', { opacity: 1, y: 0, duration: 0.9 }, 1.9)
        .to('[data-anim="chip"]', { opacity: 1, scale: 1, duration: 1, stagger: 0.12 }, 1.6);
