        ref={frameRef}
        className="relative shrink-0"
        style={{
          width: 'max(100vw, calc(100svh * 600 / 406))',
          aspectRatio: FRAME_RATIO,
          transform: 'scale(1.08)',
          opacity: 0,
        }}
