        {/* FOTO 1: sempre visível por baixo */}
        <img
          src={HERO_IMG_DEFAULT}
          srcSet={srcSetDe(ID_PADRAO)}
          sizes="100vw"
          alt="Mão usando o anel inteligente"
          draggable={false}
          fetchpriority="high"
          className="absolute inset-0 w-full h-full object-cover object-center"
