gsap.registerPlugin(ScrollTrigger);

const VIDEO = 'https://res.cloudinary.com/dwmrunhxa/video/upload/v1785710538/0802_tgabv7.mp4';

const TINTA = '#0f0f16';
const APAGADO = '#6e6e7a';

export default function Project3Video() {
