Crie um carrossel de imagens 3D em React + TypeScript usando Three.js puro (sem react-three-fiber), reproduzindo exatamente o código abaixo — é um componente completo em arquivo único, pronto pra colar e importar.

O que ele faz (pra você entender antes de mexer):
- Fileira infinita de cards com imagens, todos no mesmo plano X/Z — cada card só desliza lateralmente, nunca gira nem muda de profundidade (é isso que estruturalmente impede qualquer card de "passar na frente" da câmera).
- Curvatura óptica: cada card estica a própria altura em proporção ao quadrado da distância até o centro da cena, via vertex shader — o efeito visual é a fileira toda curvando pra cima nas bordas, sem nenhum anel 3D de verdade por trás disso.
- Cantos arredondados via signed distance field no fragment shader (não existe "border-radius" nativo pra um plano 3D).
- Drag com inércia/momentum, snap pro card mais próximo ao soltar, autoplay depois de X ms parado, parallax de câmera seguindo o mouse, e hover que desatura os cards não-focados (tint por shader, sem mudar escala pra não sobrepor vizinhos).
- Loop infinito sem emenda: a lista de imagens é repetida várias vezes lado a lado; quando o scroll passa de um ciclo completo, a posição é deslocada de volta em exatamente um ciclo — como as cópias são idênticas, o "teleporte" é invisível.
- Fallback de acessibilidade: uma lista <ul> visualmente escondida (mas lida por leitor de tela/crawler) com o alt de cada imagem, já que o carrossel em si é um <canvas> WebGL sem texto real.

Dependências: só precisa de `react`, `react-dom` e `three` instalados no projeto de destino — nenhuma outra lib, nenhum arquivo CSS, sem react-three-fiber.

Arquivo único — cole exatamente como está em `CurveImageCarousel.bundle.tsx`:

```tsx
/**
 * CurveImageCarousel.bundle.tsx
 *
 * Single-file version of the Curve Image Carousel, for platforms (like a
 * "copy the whole template" button) that only support pasting one file.
 * This is a straight concatenation of the modular source - same
 * behavior, same defaults, same comments - just with the internal
 * imports between files inlined instead. If you can use multiple files,
 * prefer the modular version in `src/components/CurveImageCarousel/`;
 * it's the same code, easier to navigate.
 *
 * Requires `react`, `react-dom` and `three` as dependencies. No other
 * dependency, no CSS file, no react-three-fiber.
 *
 * Usage:
 *   import { CurveImageCarousel } from './CurveImageCarousel.bundle';
 *
 *   <CurveImageCarousel
 *     images={[
 *       { src: '/img/1.jpg', alt: 'Projeto 1' },
 *       { src: '/img/2.jpg', alt: 'Projeto 2' },
 *     ]}
 *   />
 */

import { useEffect, useRef, type CSSProperties, type RefObject } from 'react';
import * as THREE from 'three';

// =============================================================================
// constants
// =============================================================================

/** Width of a single card, in world units. */
const DEFAULT_ITEM_WIDTH = 0.72;

/** Height of a single card, in world units. */
const DEFAULT_ITEM_HEIGHT = 0.97;

/** Gap between cards, as a percentage of `itemWidth`. */
const DEFAULT_GAP = 10;

/**
 * Corner radius, in world units. Clamped in resolveConfig() to never
 * exceed half of the smaller of `itemWidth`/`itemHeight` - past that
 * point the rounded-rect SDF in the fragment shader would describe a
 * shape smaller than the card ever actually reaches.
 */
const DEFAULT_BORDER_RADIUS = 0.08;

/**
 * Curl strength, as a percentage - a card's height is scaled by
 * `1 + (curve/100) * distanceFromCenter^2` in the vertex shader.
 */
const DEFAULT_CURVE_AMOUNT = 12;

/**
 * How many times the image list is tiled into actual card meshes. Needs
 * to be generous enough that, for any realistic viewport width and any
 * amount of dragging, there is always tiled content on both sides of the
 * visible area - see the `cycleWidth` wraparound in the render loop for
 * why the tiling has to stay well ahead of the camera's view.
 */
const DEFAULT_REPEAT_COUNT = 8;

/**
 * Segments along each axis of every card's PlaneGeometry. The curve
 * shader reads each vertex's own world position, so more segments let
 * the curl vary smoothly *within* a single card's width, not just
 * between cards.
 */
const CURVE_WIDTH_SEGMENTS = 20;
const CURVE_HEIGHT_SEGMENTS = 20;

/** World units the scroll position moves per pixel of horizontal drag. */
const DEFAULT_DRAG_SENSITIVITY = 0.0055;

/**
 * Per-second exponential decay applied to the drag-release velocity.
 * Expressed as "how much velocity survives after 1 second" - 0 kills all
 * momentum instantly, values approaching 1 slide forever.
 */
const DEFAULT_MOMENTUM = 0.94;

/**
 * Spring-like follow speed of the actual scroll position chasing the
 * `targetScrollX` the interaction layer computes:
 * `currentScrollX += (targetScrollX - currentScrollX) * damping * dt`.
 * Larger = snappier follow, smaller = laggier, heavier-feeling carousel.
 */
const DEFAULT_DAMPING = 6;

/** World units/second the strip scrolls on its own once the user goes idle. */
const DEFAULT_AUTOPLAY_SPEED = 0.3;

/** Whether the strip should settle on the nearest card after momentum runs out. */
const DEFAULT_SNAP = true;

/** Milliseconds of no pointer/wheel activity before autoplay resumes. */
const AUTOPLAY_IDLE_DELAY_MS = 1600;

/** Velocity (world units/second) below which we consider momentum "settled". */
const VELOCITY_EPSILON = 0.001;

/**
 * How far back (world units) the camera sits from the card row. Chosen
 * so a card of `DEFAULT_ITEM_HEIGHT` fills roughly 45% of the viewport
 * height at `DEFAULT_CAMERA_FOV`.
 */
const DEFAULT_CAMERA_DISTANCE = 2.9;

/**
 * Vertical field of view, in degrees, of the PerspectiveCamera - wide,
 * so a close camera can still see several cards across the row at once.
 */
const DEFAULT_CAMERA_FOV = 75;

/** Near clipping plane. */
const CAMERA_NEAR = 0.1;

/** Far clipping plane. */
const CAMERA_FAR = 20;

/** Maximum horizontal camera parallax offset (world units) from pointer position. */
const DEFAULT_CAMERA_PAN = 0.15;

/** How quickly the camera chases its parallax target - same shape as DEFAULT_DAMPING. */
const CAMERA_PAN_DAMPING = 4;

/**
 * Uniform scale multiplier applied to a card under the pointer. Left at
 * 1 (no growth) by default: scaling a card up makes it overlap its
 * neighbor, and since every card sits at the exact same Z depth, the
 * raycaster has no reliable way to pick a winner in that overlap - which
 * card counts as "hovered" flickers between the two, frame to frame, and
 * since a non-hovered card is tinted darker, that flicker reads as a
 * shadow trembling under the pointer. Hover feedback is carried entirely
 * by the color tint instead, which needs no geometry change and so can
 * never create this kind of overlap.
 */
const DEFAULT_HOVER_SCALE = 1;

/**
 * How strongly non-hovered cards are desaturated, from 0 (full color,
 * grayscale disabled) to 1 (fully gray). Implemented as a `tint` uniform
 * lerp in the card's ShaderMaterial.
 */
const DEFAULT_HOVER_GRAYSCALE = 0.6;

/** Follow speed for the per-card hover scale/tint animation. */
const HOVER_ANIMATION_DAMPING = 10;

/** Hard ceiling on devicePixelRatio - stops 3x/4x phones tanking the frame rate. */
const DEFAULT_PIXEL_RATIO_CAP = 2;

/** Largest delta-time (seconds) fed to the simulation in a single frame. */
const MAX_DELTA_SECONDS = 1 / 15;

/**
 * Wheel-to-scroll multiplier, kept separate from drag sensitivity because
 * `deltaY` is expressed in very different units (and varies by device/browser).
 */
const WHEEL_SENSITIVITY = 0.003;

/** Pointer must move less than this many CSS pixels for a release to count as a click. */
const DRAG_CLICK_THRESHOLD_PX = 6;

// =============================================================================
// types
// =============================================================================

/** One image to place on the carousel. */
export interface CarouselImage {
  /** URL passed straight to THREE.TextureLoader. */
  src: string;
  /** Optional destination the card represents - handed back via onCardSelect. */
  link?: string;
  /** Optional accessible label, surfaced through a visually-hidden fallback list. */
  alt?: string;
}

/** Public configuration surface of <CurveImageCarousel />. */
export interface CurveImageCarouselProps {
  images: CarouselImage[];

  itemWidth?: number;
  itemHeight?: number;
  /**
   * Corner radius of each card, in world units. Rounded via a signed
   * distance field in the fragment shader - there is no native
   * "border-radius" for a 3D plane, so out-of-radius pixels are
   * discarded instead.
   */
  borderRadius?: number;
  /**
   * Gap between cards, as a percentage of `itemWidth` (10 = 10% extra
   * space on top of the card's own width).
   */
  gap?: number;
  /**
   * Strength of the curl, as a percentage. A card's height is scaled by
   * `1 + (curveAmount / 100) * distanceFromCenter^2` in the vertex
   * shader, so cards further from center stretch taller, reading as the
   * whole row curling upward at the edges.
   */
  curveAmount?: number;
  /**
   * How many times the image list is repeated into actual card meshes,
   * so there is always enough tiled content to scroll through
   * indefinitely in either direction without a visible seam.
   */
  repeatCount?: number;

  dragSensitivity?: number;
  momentum?: number;
  damping?: number;
  autoplaySpeed?: number;
  snap?: boolean;

  cameraPan?: number;
  cameraFov?: number;

  hoverScale?: number;
  hoverGrayscale?: number;

  pixelRatioCap?: number;

  className?: string;
  style?: CSSProperties;

  /** Called when a card is clicked/tapped, only if the pointer did not drag. */
  onCardSelect?: (image: CarouselImage, index: number) => void;
}

/** Fully-resolved configuration - every optional prop has a concrete value. */
type CarouselConfig = Required<
  Omit<CurveImageCarouselProps, 'images' | 'className' | 'style' | 'onCardSelect'>
> & {
  /** `itemWidth * (1 + gap / 100)` - the actual world-unit distance between adjacent card centers. */
  spacing: number;
};

/**
 * A stable object whose `.current` is swapped for a freshly-resolved
 * CarouselConfig on every render. Long-lived closures (interaction
 * handlers, the render loop) hold onto this object - never a plain
 * CarouselConfig - so they always see the latest prop values without
 * needing to be re-created whenever a prop that doesn't affect the actual
 * WebGL scene graph changes.
 */
interface ConfigRef {
  current: CarouselConfig;
}

/** Uniforms for the curl/curve ShaderMaterial. */
interface CurveMaterialUniforms {
  /** The card's texture. Starts null and is filled in once the texture resolves. */
  map: THREE.IUniform<THREE.Texture | null>;
  /** Curl strength. */
  curve: THREE.IUniform<number>;
  /** Multiplies the sampled texel's RGB - white is full color, gray desaturates for hover. */
  tint: THREE.IUniform<THREE.Color>;
  /** The card's (itemWidth, itemHeight), in world units - keeps rounded corners circular, not elliptical. */
  cardSize: THREE.IUniform<THREE.Vector2>;
  /** Corner radius, in world units. */
  borderRadius: THREE.IUniform<number>;
}

type CurveShaderMaterial = THREE.ShaderMaterial & {
  uniforms: CurveMaterialUniforms;
};

/** Per-card state that does not belong to Three.js's own userData typing but is stored there. */
interface CardUserData {
  /** Index into the (possibly repeated) mesh sequence this card was built from. */
  meshIndex: number;
  /** Index into the original `images` array this specific card displays. */
  imageIndex: number;
  /** This card's fixed X position, in world units, before scroll/wrap is applied. */
  baseX: number;
  /** Optional link carried over from CarouselImage. */
  link?: string;
  /** Current interpolated uniform scale multiplier, animated toward targetScale. */
  currentScale: number;
  /** Scale the hover animation is currently chasing. */
  targetScale: number;
  /** Whether the pointer is currently over this card. */
  hovered: boolean;
}

/** A card mesh with its userData narrowed to CardUserData and its material narrowed to the curve shader. */
type CardMesh = THREE.Mesh<THREE.BufferGeometry, CurveShaderMaterial> & {
  userData: CardUserData;
};

/**
 * Mutable, per-instance runtime state shared between the mount effect,
 * the interaction handlers and the render loop. Using refs (rather than
 * React state) is deliberate: this data changes up to the display's
 * refresh rate and must never trigger a React re-render.
 */
interface CarouselRuntimeRefs {
  renderer: THREE.WebGLRenderer;
  scene: THREE.Scene;
  camera: THREE.PerspectiveCamera;
  group: THREE.Group;
  raycaster: THREE.Raycaster;
  cards: CardMesh[];

  /** Horizontal scroll position (world units) the strip is actually rendered at this frame. */
  currentScrollX: number;
  /** Scroll position the strip is chasing - set by drag, wheel, momentum, autoplay or snap. */
  targetScrollX: number;
  /** Velocity (world units/second) carried by momentum after a drag/wheel release. */
  scrollVelocity: number;
  /**
   * World-unit width of one full, seamless repeat of the image sequence
   * (`spacing * images.length`). Whenever `currentScrollX`/`targetScrollX`
   * would drift past this in either direction, both are shifted back by
   * exactly one cycle - because the card sequence tiles perfectly, that
   * shift is invisible, which is what makes the scroll loop forever
   * without ever needing to wrap around a circle.
   */
  cycleWidth: number;

  isDragging: boolean;
  isPointerOverCanvas: boolean;
  /** Normalized device coordinates (-1..1) of the last known pointer position. */
  pointerNDC: THREE.Vector2;
  /** Timestamp (ms, performance.now()) of the last drag/wheel input. */
  lastInteractionAt: number;

  hoveredCard: CardMesh | null;

  /** requestAnimationFrame id of the in-flight frame, or null when the loop is stopped. */
  frameId: number | null;
  /** Whether the render loop should keep scheduling frames (false while offscreen/disposed). */
  isRunning: boolean;
  /** Set once on unmount/dispose to make any late async callback (e.g. a texture load) a no-op. */
  isDisposed: boolean;
}

// =============================================================================
// math helpers
// =============================================================================

/** Clamp `value` into the inclusive [min, max] range. */
function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

/**
 * Frame-rate independent "follow": moves `current` toward `target` in
 * proportion to how far behind it is, scaled by `damping` and `dt`:
 *
 *   delta = target - current
 *   current += delta * damping * dt
 *
 * A linear (not exponential) approximation of a spring - simple and
 * predictable, at the cost of being able to overshoot if `damping * dt`
 * exceeds 1. Every caller here uses damping values well within the safe
 * range for normal frame rates.
 */
function dampTowards(current: number, target: number, damping: number, dt: number): number {
  const delta = target - current;
  return current + delta * damping * dt;
}

/**
 * Converts a `damping` rate into the 0-1 interpolation factor expected by
 * APIs like THREE.Color.lerp ("how far to move toward the target on this
 * call"), using the exponential decay identity `1 - e^(-damping * dt)`.
 * Unlike `dampTowards`, this can never overshoot.
 */
function dampFactor(damping: number, dt: number): number {
  return 1 - Math.exp(-damping * dt);
}

/**
 * Converts the "how much velocity survives after 1 full second" momentum
 * constant (0-1) into the per-frame multiplier for an arbitrary `dt`,
 * using the exponential decay identity `momentum^dt = e^(dt * ln(momentum))`.
 * Without this, momentum would visibly decay faster on high refresh-rate
 * displays than on low ones.
 */
function applyMomentumDecay(velocity: number, momentum: number, dt: number): number {
  const decayFactor = Math.pow(momentum, dt * 60);
  return velocity * decayFactor;
}

/**
 * Given the strip's current scroll position and the fixed spacing
 * between card centers, returns the scroll value that puts the nearest
 * card exactly centered.
 */
function nearestSnapValue(current: number, step: number): number {
  return Math.round(current / step) * step;
}

/**
 * Wraps `value` into the centered range `[-window / 2, window / 2)`.
 * This is the seamless-infinite-loop primitive: as long as `window`
 * matches the world-unit width of one full, exactly-tiled repeat of
 * content, wrapping a scroll position through it is visually
 * undetectable - every position maps to an identical-looking layout one
 * cycle over.
 */
function wrapToWindow(value: number, windowSize: number): number {
  const wrapped = ((value % windowSize) + windowSize) % windowSize;
  return wrapped >= windowSize / 2 ? wrapped - windowSize : wrapped;
}

// =============================================================================
// geometry
// =============================================================================

/**
 * Builds the plain, segmented PlaneGeometry every card needs. The curve
 * itself is a vertex-shader effect (see buildCurveMaterial below), not a
 * CPU-side deformation - the segment count still matters even though the
 * geometry itself stays flat, because the shader reads each vertex's own
 * world X position, so a finer mesh lets the curl vary smoothly across a
 * single card's own width.
 */
function buildCurvedPlaneGeometry(width: number, height: number): THREE.PlaneGeometry {
  return new THREE.PlaneGeometry(width, height, CURVE_WIDTH_SEGMENTS, CURVE_HEIGHT_SEGMENTS);
}

// =============================================================================
// curve shader material
// =============================================================================

/**
 * The curl is deliberately NOT a per-card cylindrical bend baked into
 * the geometry. Instead, a vertex shader stretches a card's own height
 * in proportion to the *square* of how far that card's world X position
 * sits from the scene's center:
 *
 *   distanceFromCenter = abs((modelMatrix * vec4(position, 1)).x)
 *   newPosition.y *= 1 + (curve / 100) * distanceFromCenter^2
 *
 * Cards near center are barely stretched; cards further out grow
 * quadratically taller. Combined with a camera looking at a perfectly
 * flat, straight row of cards, that stretch is what reads as the whole
 * strip curling upward at the edges - every card stays on the same flat
 * X/Z plane, none of them ever rotate or gain depth, so nothing can ever
 * be "behind" or "in front of" anything else. That is what structurally
 * rules out a card ever appearing to pass in front of the camera: there
 * is no ring, no depth axis for a card to travel along, only a straight
 * line a card slides sideways on before scrolling out of the camera's view.
 */
const CURVE_VERTEX_SHADER = /* glsl */ `
  uniform float curve;
  varying vec2 vCardUV;

  void main() {
    vCardUV = uv;

    vec3 curvedPosition = position;
    float distanceFromCenter = abs((modelMatrix * vec4(position, 1.0)).x);
    curvedPosition.y *= 1.0 + (curve / 100.0) * pow(distanceFromCenter, 2.0);

    gl_Position = projectionMatrix * modelViewMatrix * vec4(curvedPosition, 1.0);
  }
`;

const CURVE_FRAGMENT_SHADER = /* glsl */ `
  uniform sampler2D map;
  uniform vec3 tint;
  uniform vec2 cardSize;
  uniform float borderRadius;
  varying vec2 vCardUV;

  // Rounded-rectangle signed distance field, evaluated in world units (not
  // raw 0-1 UV space) so the corner radius reads as a true circular arc
  // instead of an ellipse squashed by the card's own aspect ratio.
  float roundedBoxDistance(vec2 point, vec2 halfSize, float radius) {
    vec2 d = abs(point) - halfSize + radius;
    return length(max(d, 0.0)) - radius;
  }

  void main() {
    vec2 worldPoint = (vCardUV - 0.5) * cardSize;
    float dist = roundedBoxDistance(worldPoint, cardSize * 0.5, borderRadius);
    if (dist > 0.0) {
      discard;
    }

    vec4 texel = texture2D(map, vCardUV);
    gl_FragColor = vec4(texel.rgb * tint, texel.a);
  }
`;

/**
 * Creates one card's material. Every card gets its own ShaderMaterial
 * instance (not a shared one) because `tint` is animated per-card, every
 * frame, while a card is hovered or not.
 */
function buildCurveMaterial(
  curveAmount: number,
  itemWidth: number,
  itemHeight: number,
  borderRadius: number,
): CurveShaderMaterial {
  return new THREE.ShaderMaterial({
    uniforms: {
      map: { value: null },
      curve: { value: curveAmount },
      tint: { value: new THREE.Color(0xffffff) },
      cardSize: { value: new THREE.Vector2(itemWidth, itemHeight) },
      borderRadius: { value: borderRadius },
    },
    vertexShader: CURVE_VERTEX_SHADER,
    fragmentShader: CURVE_FRAGMENT_SHADER,
    transparent: true,
    side: THREE.DoubleSide,
  }) as CurveShaderMaterial;
}

// =============================================================================
// texture loading
// =============================================================================

const textureLoader = new THREE.TextureLoader();
textureLoader.setCrossOrigin('anonymous');

/**
 * Loads a single image as a THREE.Texture, configured the way every card
 * on this carousel needs: sRGB color space, clamp-to-edge wrapping, and
 * linear filtering with no mipmaps (these textures are shown at close to
 * their native resolution on a non-repeating surface, where mipmapping
 * buys nothing but VRAM).
 */
function loadCarouselTexture(url: string): Promise<THREE.Texture> {
  return new Promise((resolve, reject) => {
    textureLoader.load(
      url,
      (texture) => {
        texture.colorSpace = THREE.SRGBColorSpace;
        texture.wrapS = THREE.ClampToEdgeWrapping;
        texture.wrapT = THREE.ClampToEdgeWrapping;
        texture.minFilter = THREE.LinearFilter;
        texture.magFilter = THREE.LinearFilter;
        texture.generateMipmaps = false;
        texture.needsUpdate = true;
        resolve(texture);
      },
      undefined,
      (error) => reject(error),
    );
  });
}

/** Releases GPU memory for a texture. Safe to call on `null`/`undefined`. */
function disposeTexture(texture: THREE.Texture | null | undefined): void {
  texture?.dispose();
}

// =============================================================================
// interaction (pointer/wheel -> refs)
// =============================================================================

/** The single most recent pointer sample during a drag, used to derive release velocity. */
interface DragSample {
  clientX: number;
  timestamp: number;
}

/**
 * All raw DOM event handling for the carousel lives here, deliberately
 * separated from the render loop: this only ever *writes intent*
 * (target scroll, velocity, drag state, pointer position) into the
 * shared refs. It never reads a clock or advances any animation itself -
 * that responsibility belongs entirely to the render loop.
 */
function attachInteractionHandlers(
  canvas: HTMLCanvasElement,
  refs: CarouselRuntimeRefs,
  configRef: ConfigRef,
): () => void {
  let previousSample: DragSample | null = null;
  let activePointerId: number | null = null;

  const markInteraction = () => {
    refs.lastInteractionAt = performance.now();
  };

  const updatePointerNDC = (clientX: number, clientY: number) => {
    const rect = canvas.getBoundingClientRect();
    refs.pointerNDC.x = ((clientX - rect.left) / rect.width) * 2 - 1;
    refs.pointerNDC.y = -((clientY - rect.top) / rect.height) * 2 + 1;
  };

  const handlePointerEnter = () => {
    refs.isPointerOverCanvas = true;
  };

  const endDrag = () => {
    if (activePointerId !== null && canvas.hasPointerCapture(activePointerId)) {
      canvas.releasePointerCapture(activePointerId);
    }
    activePointerId = null;
    previousSample = null;
    refs.isDragging = false;
    canvas.style.cursor = refs.hoveredCard ? 'pointer' : 'grab';
    markInteraction();
  };

  const handlePointerLeave = (event: PointerEvent) => {
    refs.isPointerOverCanvas = false;
    if (refs.isDragging && event.pointerId === activePointerId) {
      endDrag();
    }
  };

  const handlePointerDown = (event: PointerEvent) => {
    if (event.pointerType === 'mouse' && event.button !== 0) return;

    activePointerId = event.pointerId;
    canvas.setPointerCapture(event.pointerId);

    refs.isDragging = true;
    refs.scrollVelocity = 0;
    previousSample = { clientX: event.clientX, timestamp: performance.now() };

    updatePointerNDC(event.clientX, event.clientY);
    markInteraction();
    canvas.style.cursor = 'grabbing';
  };

  const handlePointerMove = (event: PointerEvent) => {
    updatePointerNDC(event.clientX, event.clientY);

    if (!refs.isDragging || event.pointerId !== activePointerId || !previousSample) {
      return;
    }

    const now = performance.now();
    const deltaX = event.clientX - previousSample.clientX;
    const deltaSeconds = Math.max((now - previousSample.timestamp) / 1000, 1 / 1000);

    // Dragging the pointer to the right should visually slide the cards
    // to the right too - since a card's rendered X is `baseX -
    // currentScrollX`, decreasing the scroll target is what makes cards
    // move right, hence the negative sign here.
    const scrollDelta = -deltaX * configRef.current.dragSensitivity;
    refs.targetScrollX += scrollDelta;
    refs.scrollVelocity = scrollDelta / deltaSeconds;

    previousSample = { clientX: event.clientX, timestamp: now };
    markInteraction();
  };

  const handlePointerUp = (event: PointerEvent) => {
    if (event.pointerId !== activePointerId) return;
    endDrag();
  };

  const handleWheel = (event: WheelEvent) => {
    event.preventDefault();

    const scrollDelta = event.deltaY * WHEEL_SENSITIVITY;
    refs.targetScrollX += scrollDelta;
    refs.scrollVelocity = scrollDelta * 6;
    markInteraction();
  };

  canvas.addEventListener('pointerenter', handlePointerEnter);
  canvas.addEventListener('pointerleave', handlePointerLeave);
  canvas.addEventListener('pointerdown', handlePointerDown);
  canvas.addEventListener('pointermove', handlePointerMove);
  canvas.addEventListener('pointerup', handlePointerUp);
  canvas.addEventListener('pointercancel', handlePointerUp);
  canvas.addEventListener('wheel', handleWheel, { passive: false });
  canvas.style.cursor = 'grab';

  return function detachInteractionHandlers() {
    canvas.removeEventListener('pointerenter', handlePointerEnter);
    canvas.removeEventListener('pointerleave', handlePointerLeave);
    canvas.removeEventListener('pointerdown', handlePointerDown);
    canvas.removeEventListener('pointermove', handlePointerMove);
    canvas.removeEventListener('pointerup', handlePointerUp);
    canvas.removeEventListener('pointercancel', handlePointerUp);
    canvas.removeEventListener('wheel', handleWheel);
  };
}

// =============================================================================
// render loop
// =============================================================================

// Scratch color objects, reused every frame instead of allocated fresh.
const grayscaleScratch = new THREE.Color();
const whiteScratch = new THREE.Color(0xffffff);

function resolveTargetScroll(refs: CarouselRuntimeRefs, config: CarouselConfig, dt: number): void {
  if (refs.isDragging) return;

  const hasMomentum = Math.abs(refs.scrollVelocity) > VELOCITY_EPSILON;

  if (hasMomentum) {
    refs.targetScrollX += refs.scrollVelocity * dt;
    refs.scrollVelocity = applyMomentumDecay(refs.scrollVelocity, config.momentum, dt);
    return;
  }

  const idleForMs = performance.now() - refs.lastInteractionAt;
  const isAutoplaying = idleForMs > AUTOPLAY_IDLE_DELAY_MS && config.autoplaySpeed !== 0;

  if (isAutoplaying) {
    // Once autoplay has taken over, it alone drives targetScrollX - it
    // deliberately does NOT also re-run the snap correction below, which
    // would otherwise fight the continuous scroll every single frame.
    refs.targetScrollX += config.autoplaySpeed * dt;
    return;
  }

  if (config.snap) {
    refs.targetScrollX = nearestSnapValue(refs.targetScrollX, config.spacing);
  }
}

function updateScrollPosition(refs: CarouselRuntimeRefs, config: CarouselConfig, dt: number): void {
  refs.currentScrollX = dampTowards(refs.currentScrollX, refs.targetScrollX, config.damping, dt);

  // Seamless infinite loop: once the scroll has moved a full cycle's
  // worth of tiled content, shift both the live and target position back
  // by exactly one cycle width, in the same frame - the card sequence
  // tiles exactly, so this reset is invisible.
  if (Math.abs(refs.currentScrollX) >= refs.cycleWidth / 2) {
    const cycles = Math.round(refs.currentScrollX / refs.cycleWidth);
    const shift = cycles * refs.cycleWidth;
    refs.currentScrollX -= shift;
    refs.targetScrollX -= shift;
  }

  for (const card of refs.cards) {
    const rawX = card.userData.baseX - refs.currentScrollX;
    card.position.x = wrapToWindow(rawX, refs.cycleWidth * 4);
  }
}

function setHoveredCard(refs: CarouselRuntimeRefs, next: CardMesh | null, config: CarouselConfig): void {
  if (refs.hoveredCard === next) return;

  if (refs.hoveredCard) {
    refs.hoveredCard.userData.hovered = false;
    refs.hoveredCard.userData.targetScale = 1;
  }

  if (next) {
    next.userData.hovered = true;
    next.userData.targetScale = config.hoverScale;
  }

  refs.hoveredCard = next;

  if (!refs.isDragging) {
    refs.renderer.domElement.style.cursor = next ? 'pointer' : 'grab';
  }
}

function updateHoverRaycast(refs: CarouselRuntimeRefs, config: CarouselConfig): void {
  if (refs.isDragging || !refs.isPointerOverCanvas) {
    setHoveredCard(refs, null, config);
    return;
  }

  refs.raycaster.setFromCamera(refs.pointerNDC, refs.camera);
  const intersections = refs.raycaster.intersectObjects(refs.cards, false);
  const nextHovered = (intersections[0]?.object as CardMesh | undefined) ?? null;

  setHoveredCard(refs, nextHovered, config);
}

function updateCardAnimations(refs: CarouselRuntimeRefs, config: CarouselConfig, dt: number): void {
  const grayAmount = clamp(config.hoverGrayscale, 0, 1);
  grayscaleScratch.setRGB(1 - grayAmount, 1 - grayAmount, 1 - grayAmount);
  const tintLerpFactor = dampFactor(HOVER_ANIMATION_DAMPING, dt);

  for (const card of refs.cards) {
    const data = card.userData;

    data.currentScale = dampTowards(data.currentScale, data.targetScale, HOVER_ANIMATION_DAMPING, dt);
    card.scale.setScalar(data.currentScale);

    const targetTint = data.hovered || grayAmount === 0 ? whiteScratch : grayscaleScratch;
    card.material.uniforms.tint.value.lerp(targetTint, tintLerpFactor);
  }
}

function updateCameraParallax(refs: CarouselRuntimeRefs, config: CarouselConfig, dt: number): void {
  const targetX = refs.isPointerOverCanvas ? refs.pointerNDC.x * config.cameraPan : 0;
  const targetY = refs.isPointerOverCanvas ? refs.pointerNDC.y * config.cameraPan * 0.5 : 0;

  refs.camera.position.x = dampTowards(refs.camera.position.x, targetX, CAMERA_PAN_DAMPING, dt);
  refs.camera.position.y = dampTowards(refs.camera.position.y, targetY, CAMERA_PAN_DAMPING, dt);
  refs.camera.lookAt(refs.camera.position.x, refs.camera.position.y, 0);
}

interface RenderLoopHandle {
  start: () => void;
  stop: () => void;
}

/**
 * Builds (but does not start) the carousel's render loop. Returned as a
 * `{ start, stop }` pair so an IntersectionObserver can pause/resume it
 * without needing to know anything about its internals.
 */
function createRenderLoop(refs: CarouselRuntimeRefs, configRef: ConfigRef): RenderLoopHandle {
  let previousTimestamp: number | null = null;

  function tick(timestamp: number) {
    if (refs.isDisposed || !refs.isRunning) {
      refs.frameId = null;
      return;
    }

    const config = configRef.current;

    const rawDeltaSeconds = previousTimestamp === null ? 0 : (timestamp - previousTimestamp) / 1000;
    previousTimestamp = timestamp;
    const dt = clamp(rawDeltaSeconds, 0, MAX_DELTA_SECONDS);

    resolveTargetScroll(refs, config, dt);
    updateScrollPosition(refs, config, dt);
    updateHoverRaycast(refs, config);
    updateCardAnimations(refs, config, dt);
    updateCameraParallax(refs, config, dt);

    refs.renderer.render(refs.scene, refs.camera);

    refs.frameId = requestAnimationFrame(tick);
  }

  return {
    start() {
      if (refs.frameId !== null || refs.isDisposed) return;
      refs.isRunning = true;
      previousTimestamp = null;
      refs.frameId = requestAnimationFrame(tick);
    },
    stop() {
      refs.isRunning = false;
      if (refs.frameId !== null) {
        cancelAnimationFrame(refs.frameId);
        refs.frameId = null;
      }
    },
  };
}

// =============================================================================
// useCarousel hook
// =============================================================================

function resolveConfig(props: CurveImageCarouselProps): CarouselConfig {
  const itemWidth = props.itemWidth ?? DEFAULT_ITEM_WIDTH;
  const gap = props.gap ?? DEFAULT_GAP;
  const itemHeight = props.itemHeight ?? DEFAULT_ITEM_HEIGHT;
  const requestedBorderRadius = props.borderRadius ?? DEFAULT_BORDER_RADIUS;

  return {
    itemWidth,
    itemHeight,
    borderRadius: Math.min(requestedBorderRadius, Math.min(itemWidth, itemHeight) / 2),
    gap,
    spacing: itemWidth * (1 + gap / 100),
    curveAmount: props.curveAmount ?? DEFAULT_CURVE_AMOUNT,
    repeatCount: props.repeatCount ?? DEFAULT_REPEAT_COUNT,
    dragSensitivity: props.dragSensitivity ?? DEFAULT_DRAG_SENSITIVITY,
    momentum: props.momentum ?? DEFAULT_MOMENTUM,
    damping: props.damping ?? DEFAULT_DAMPING,
    autoplaySpeed: props.autoplaySpeed ?? DEFAULT_AUTOPLAY_SPEED,
    snap: props.snap ?? DEFAULT_SNAP,
    cameraPan: props.cameraPan ?? DEFAULT_CAMERA_PAN,
    cameraFov: props.cameraFov ?? DEFAULT_CAMERA_FOV,
    hoverScale: props.hoverScale ?? DEFAULT_HOVER_SCALE,
    hoverGrayscale: props.hoverGrayscale ?? DEFAULT_HOVER_GRAYSCALE,
    pixelRatioCap: props.pixelRatioCap ?? DEFAULT_PIXEL_RATIO_CAP,
  };
}

/**
 * Owns the WebGLRenderer/Scene/Camera lifecycle, builds the straight row
 * of card meshes (tiled several times over for a seamless infinite
 * loop), wires up interaction + the render loop, and tears every GPU
 * resource back down on unmount.
 */
function useCarousel(containerRef: RefObject<HTMLDivElement>, props: CurveImageCarouselProps): void {
  const configRef = useRef<CarouselConfig>(resolveConfig(props));
  configRef.current = resolveConfig(props);

  const runtimeRef = useRef<CarouselRuntimeRefs | null>(null);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;
    if (props.images.length === 0) return;

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, configRef.current.pixelRatioCap));
    renderer.setSize(container.clientWidth, container.clientHeight, false);
    renderer.domElement.style.display = 'block';
    renderer.domElement.style.width = '100%';
    renderer.domElement.style.height = '100%';
    container.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    const group = new THREE.Group();
    scene.add(group);

    const camera = new THREE.PerspectiveCamera(
      configRef.current.cameraFov,
      container.clientWidth / Math.max(container.clientHeight, 1),
      CAMERA_NEAR,
      CAMERA_FAR,
    );
    camera.position.set(0, 0, DEFAULT_CAMERA_DISTANCE);
    camera.lookAt(0, 0, 0);

    const raycaster = new THREE.Raycaster();

    const cycleWidth = configRef.current.spacing * props.images.length;

    const refs: CarouselRuntimeRefs = {
      renderer,
      scene,
      camera,
      group,
      raycaster,
      cards: [],
      currentScrollX: 0,
      targetScrollX: 0,
      scrollVelocity: 0,
      cycleWidth,
      isDragging: false,
      isPointerOverCanvas: false,
      pointerNDC: new THREE.Vector2(-10, -10),
      lastInteractionAt: performance.now(),
      hoveredCard: null,
      frameId: null,
      isRunning: false,
      isDisposed: false,
    };
    runtimeRef.current = refs;

    let cancelled = false;

    const totalMeshCount = props.images.length * configRef.current.repeatCount;
    const centerIndex = (totalMeshCount - 1) / 2;

    const sharedGeometry = buildCurvedPlaneGeometry(
      configRef.current.itemWidth,
      configRef.current.itemHeight,
    );

    for (let meshIndex = 0; meshIndex < totalMeshCount; meshIndex += 1) {
      const imageIndex = meshIndex % props.images.length;
      const image = props.images[imageIndex];
      const baseX = (meshIndex - centerIndex) * configRef.current.spacing;

      const material = buildCurveMaterial(
        configRef.current.curveAmount,
        configRef.current.itemWidth,
        configRef.current.itemHeight,
        configRef.current.borderRadius,
      );
      const mesh = new THREE.Mesh(sharedGeometry, material) as unknown as CardMesh;

      mesh.position.set(baseX, 0, 0);

      mesh.userData = {
        meshIndex,
        imageIndex,
        baseX,
        link: image.link,
        currentScale: 1,
        targetScale: 1,
        hovered: false,
      };

      group.add(mesh);
      refs.cards.push(mesh);

      loadCarouselTexture(image.src)
        .then((texture) => {
          if (cancelled || refs.isDisposed) {
            texture.dispose();
            return;
          }
          material.uniforms.map.value = texture;
        })
        .catch((error: unknown) => {
          console.error(`CurveImageCarousel: failed to load "${image.src}"`, error);
        });
    }

    const detachInteraction = attachInteractionHandlers(renderer.domElement, refs, configRef);
    const loop = createRenderLoop(refs, configRef);

    let pointerDownPosition: { x: number; y: number } | null = null;

    const handlePointerDownForClick = (event: PointerEvent) => {
      pointerDownPosition = { x: event.clientX, y: event.clientY };
    };
    const handlePointerUpForClick = (event: PointerEvent) => {
      if (!pointerDownPosition) return;
      const movedDistance = Math.hypot(
        event.clientX - pointerDownPosition.x,
        event.clientY - pointerDownPosition.y,
      );
      pointerDownPosition = null;

      if (movedDistance > DRAG_CLICK_THRESHOLD_PX) return;
      if (!refs.hoveredCard) return;

      const { imageIndex } = refs.hoveredCard.userData;
      props.onCardSelect?.(props.images[imageIndex], imageIndex);
    };
    renderer.domElement.addEventListener('pointerdown', handlePointerDownForClick);
    renderer.domElement.addEventListener('pointerup', handlePointerUpForClick);

    const resizeObserver = new ResizeObserver((entries) => {
      const entry = entries[0];
      if (!entry) return;
      const { width, height } = entry.contentRect;
      if (width === 0 || height === 0) return;

      renderer.setSize(width, height, false);
      camera.aspect = width / height;
      camera.updateProjectionMatrix();
    });
    resizeObserver.observe(container);

    const intersectionObserver = new IntersectionObserver(
      ([entry]) => {
        if (!entry) return;
        if (entry.isIntersecting) {
          loop.start();
        } else {
          loop.stop();
        }
      },
      { threshold: 0 },
    );
    intersectionObserver.observe(container);

    loop.start();

    return function disposeCarousel() {
      cancelled = true;
      refs.isDisposed = true;
      loop.stop();

      detachInteraction();
      renderer.domElement.removeEventListener('pointerdown', handlePointerDownForClick);
      renderer.domElement.removeEventListener('pointerup', handlePointerUpForClick);

      resizeObserver.disconnect();
      intersectionObserver.disconnect();

      refs.cards.forEach((card) => {
        disposeTexture(card.material.uniforms.map.value);
        card.material.dispose();
      });
      sharedGeometry.dispose();

      renderer.dispose();
      if (renderer.domElement.parentElement === container) {
        container.removeChild(renderer.domElement);
      }

      runtimeRef.current = null;
    };
    // Only re-runs when something changes the actual WebGL scene graph
    // (the image list, or the row's geometry-defining dimensions). Every
    // other prop is read live off `configRef` every frame, so changing
    // one of those does not tear down and rebuild the renderer. Pass a
    // stable (memoized or module-level) `images` array for best
    // performance - a new array identity on every render rebuilds the
    // whole scene on every render too.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [containerRef, props.images, props.itemWidth, props.itemHeight, props.gap, props.curveAmount, props.repeatCount]);

  useEffect(() => {
    const refs = runtimeRef.current;
    if (!refs) return;
    refs.camera.fov = props.cameraFov ?? DEFAULT_CAMERA_FOV;
    refs.camera.updateProjectionMatrix();
  }, [props.cameraFov]);

  useEffect(() => {
    const refs = runtimeRef.current;
    if (!refs) return;
    refs.renderer.setPixelRatio(Math.min(window.devicePixelRatio, props.pixelRatioCap ?? DEFAULT_PIXEL_RATIO_CAP));
  }, [props.pixelRatioCap]);
}

// =============================================================================
// component
// =============================================================================

const visuallyHiddenStyle: CSSProperties = {
  position: 'absolute',
  width: 1,
  height: 1,
  overflow: 'hidden',
  clipPath: 'inset(50%)',
  whiteSpace: 'nowrap',
};

/**
 * Thin React shell around `useCarousel`. All Three.js state lives in
 * that hook, entirely inside refs; this component's only two jobs are:
 * (1) provide the DOM container the hook mounts its `<canvas>` into, and
 * (2) render an accessible, non-visual fallback list of the same images,
 * so a WebGL carousel's content is not entirely invisible to screen
 * readers, text browsers, and search crawlers.
 */
export function CurveImageCarousel(props: CurveImageCarouselProps) {
  const containerRef = useRef<HTMLDivElement>(null);

  useCarousel(containerRef, props);

  return (
    <div
      ref={containerRef}
      className={props.className}
      style={{
        position: 'relative',
        width: '100%',
        height: '100%',
        touchAction: 'none',
        ...props.style,
      }}
    >
      <ul style={visuallyHiddenStyle}>
        {props.images.map((image, index) => (
          <li key={image.src + index}>{image.alt ?? `Slide ${index + 1}`}</li>
        ))}
      </ul>
    </div>
  );
}
```

