6. O carrossel 3D — src/components/CurveImageCarousel/CurveImageCarousel.tsx

Este é o componente mais complexo: renderiza uma fileira infinita de cards com imagens, curvados por um shader GLSL customizado (a curva NÃO é CSS, é matemática de vertex shader rodando em WebGL puro via three.js), com drag/scroll, momentum, autoplay quando ocioso, e parallax de câmera seguindo o mouse.

Você tem duas opções de organização — o resultado visual/comportamental é idêntico:

- Opção A (recomendada para colar rápido): um único arquivo CurveImageCarousel.tsx com tudo dentro (constantes, shader, matemática, hook, componente).
- Opção B (mais organizada): dividir em constants.ts, types.ts, math.ts, curveMaterial.ts, textureLoader.ts, interaction.ts, renderLoop.ts, useCarousel.ts e CurveImageCarousel.tsx, cada um só com a parte correspondente.

Peça para a IA usar o código abaixo (versão single-file, Opção A) tal como está, sem alterar nenhuma constante numérica (elas controlam a velocidade do scroll, o momentum, o ângulo da curva, o FOV da câmera etc. — mudar qualquer uma muda o "feel" do carrossel):

```tsx
/**
 * CurveImageCarousel.tsx
 *
 * Single-file version of the Curve Image Carousel.
 * Requires `react`, `react-dom` and `three` as dependencies. No other
 * dependency, no CSS file, no react-three-fiber.
 *
 * Usage:
 *   import { CurveImageCarousel } from './CurveImageCarousel';
 *
 *   <CurveImageCarousel
 *     images={[
 *       { src: '/img/1.jpg', alt: 'Projeto 1' },
 *       { src: '/img/2.jpg', alt: 'Projeto 2' },
 *     ]}
 *   />
 */

import { useEffect, useRef, type CSSProperties, type RefObject } from 'react';
import * as THREE from 'three';

// =============================================================================
// constants
// =============================================================================

const DEFAULT_ITEM_WIDTH = 0.72;
const DEFAULT_ITEM_HEIGHT = 0.97;
const DEFAULT_GAP = 10;
const DEFAULT_BORDER_RADIUS = 0.08;
const DEFAULT_CURVE_AMOUNT = 12;
const DEFAULT_REPEAT_COUNT = 8;
const CURVE_WIDTH_SEGMENTS = 20;
const CURVE_HEIGHT_SEGMENTS = 20;
const DEFAULT_DRAG_SENSITIVITY = 0.0055;
const DEFAULT_MOMENTUM = 0.94;
const DEFAULT_DAMPING = 6;
const DEFAULT_AUTOPLAY_SPEED = 0.3;
const DEFAULT_SNAP = true;
const AUTOPLAY_IDLE_DELAY_MS = 1600;
const VELOCITY_EPSILON = 0.001;
const DEFAULT_CAMERA_DISTANCE = 2.9;
const DEFAULT_CAMERA_FOV = 75;
const CAMERA_NEAR = 0.1;
const CAMERA_FAR = 20;
const DEFAULT_CAMERA_PAN = 0.15;
const CAMERA_PAN_DAMPING = 4;
const DEFAULT_HOVER_SCALE = 1;
const DEFAULT_HOVER_GRAYSCALE = 0.6;
const HOVER_ANIMATION_DAMPING = 10;
const DEFAULT_PIXEL_RATIO_CAP = 2;
const MAX_DELTA_SECONDS = 1 / 15;
const WHEEL_SENSITIVITY = 0.003;
const DRAG_CLICK_THRESHOLD_PX = 6;

// =============================================================================
// types
// =============================================================================

export interface CarouselImage {
  src: string;
  link?: string;
  alt?: string;
}

export interface CurveImageCarouselProps {
  images: CarouselImage[];
  itemWidth?: number;
  itemHeight?: number;
  borderRadius?: number;
  gap?: number;
  curveAmount?: number;
  repeatCount?: number;
  dragSensitivity?: number;
  momentum?: number;
  damping?: number;
  autoplaySpeed?: number;
  snap?: boolean;
  cameraPan?: number;
  cameraFov?: number;
  hoverScale?: number;
  hoverGrayscale?: number;
  pixelRatioCap?: number;
  className?: string;
  style?: CSSProperties;
  onCardSelect?: (image: CarouselImage, index: number) => void;
}

type CarouselConfig = Required<
  Omit<CurveImageCarouselProps, 'images' | 'className' | 'style' | 'onCardSelect'>
> & {
  spacing: number;
};

interface ConfigRef {
  current: CarouselConfig;
}

interface CurveMaterialUniforms {
  map: THREE.IUniform<THREE.Texture | null>;
  curve: THREE.IUniform<number>;
  tint: THREE.IUniform<THREE.Color>;
  cardSize: THREE.IUniform<THREE.Vector2>;
  borderRadius: THREE.IUniform<number>;
}

type CurveShaderMaterial = THREE.ShaderMaterial & {
  uniforms: CurveMaterialUniforms;
};

interface CardUserData {
  meshIndex: number;
  imageIndex: number;
  baseX: number;
  link?: string;
  currentScale: number;
  targetScale: number;
  hovered: boolean;
}

type CardMesh = THREE.Mesh<THREE.BufferGeometry, CurveShaderMaterial> & {
  userData: CardUserData;
};

interface CarouselRuntimeRefs {
  renderer: THREE.WebGLRenderer;
  scene: THREE.Scene;
  camera: THREE.PerspectiveCamera;
  group: THREE.Group;
  raycaster: THREE.Raycaster;
  cards: CardMesh[];
  currentScrollX: number;
  targetScrollX: number;
  scrollVelocity: number;
  cycleWidth: number;
  isDragging: boolean;
  isPointerOverCanvas: boolean;
  pointerNDC: THREE.Vector2;
  lastInteractionAt: number;
  hoveredCard: CardMesh | null;
  frameId: number | null;
  isRunning: boolean;
  isDisposed: boolean;
}

// =============================================================================
// math helpers
// =============================================================================

function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

function dampTowards(current: number, target: number, damping: number, dt: number): number {
  const delta = target - current;
  return current + delta * damping * dt;
}

function dampFactor(damping: number, dt: number): number {
  return 1 - Math.exp(-damping * dt);
}

function applyMomentumDecay(velocity: number, momentum: number, dt: number): number {
  const decayFactor = Math.pow(momentum, dt * 60);
  return velocity * decayFactor;
}

function nearestSnapValue(current: number, step: number): number {
  return Math.round(current / step) * step;
}

function wrapToWindow(value: number, windowSize: number): number {
  const wrapped = ((value % windowSize) + windowSize) % windowSize;
  return wrapped >= windowSize / 2 ? wrapped - windowSize : wrapped;
}

// =============================================================================
// geometry
// =============================================================================

function buildCurvedPlaneGeometry(width: number, height: number): THREE.PlaneGeometry {
  return new THREE.PlaneGeometry(width, height, CURVE_WIDTH_SEGMENTS, CURVE_HEIGHT_SEGMENTS);
}

// =============================================================================
// curve shader material
// =============================================================================

const CURVE_VERTEX_SHADER = /* glsl */ `
  uniform float curve;
  varying vec2 vCardUV;

  void main() {
    vCardUV = uv;

    vec3 curvedPosition = position;
    float distanceFromCenter = abs((modelMatrix * vec4(position, 1.0)).x);
    curvedPosition.y *= 1.0 + (curve / 100.0) * pow(distanceFromCenter, 2.0);

    gl_Position = projectionMatrix * modelViewMatrix * vec4(curvedPosition, 1.0);
  }
`;

const CURVE_FRAGMENT_SHADER = /* glsl */ `
  uniform sampler2D map;
  uniform vec3 tint;
  uniform vec2 cardSize;
  uniform float borderRadius;
  varying vec2 vCardUV;

  float roundedBoxDistance(vec2 point, vec2 halfSize, float radius) {
    vec2 d = abs(point) - halfSize + radius;
    return length(max(d, 0.0)) - radius;
  }

  void main() {
    vec2 worldPoint = (vCardUV - 0.5) * cardSize;
    float dist = roundedBoxDistance(worldPoint, cardSize * 0.5, borderRadius);
    if (dist > 0.0) {
      discard;
    }

    vec4 texel = texture2D(map, vCardUV);
    gl_FragColor = vec4(texel.rgb * tint, texel.a);
  }
`;

function buildCurveMaterial(
  curveAmount: number,
  itemWidth: number,
  itemHeight: number,
  borderRadius: number,
): CurveShaderMaterial {
  return new THREE.ShaderMaterial({
    uniforms: {
      map: { value: null },
      curve: { value: curveAmount },
      tint: { value: new THREE.Color(0xffffff) },
      cardSize: { value: new THREE.Vector2(itemWidth, itemHeight) },
      borderRadius: { value: borderRadius },
    },
    vertexShader: CURVE_VERTEX_SHADER,
    fragmentShader: CURVE_FRAGMENT_SHADER,
    transparent: true,
    side: THREE.DoubleSide,
  }) as CurveShaderMaterial;
}

// =============================================================================
// texture loading
// =============================================================================

const textureLoader = new THREE.TextureLoader();
textureLoader.setCrossOrigin('anonymous');

function loadCarouselTexture(url: string): Promise<THREE.Texture> {
  return new Promise((resolve, reject) => {
    textureLoader.load(
      url,
      (texture) => {
        texture.colorSpace = THREE.SRGBColorSpace;
        texture.wrapS = THREE.ClampToEdgeWrapping;
        texture.wrapT = THREE.ClampToEdgeWrapping;
        texture.minFilter = THREE.LinearFilter;
        texture.magFilter = THREE.LinearFilter;
        texture.generateMipmaps = false;
        texture.needsUpdate = true;
        resolve(texture);
      },
      undefined,
      (error) => reject(error),
    );
  });
}

function disposeTexture(texture: THREE.Texture | null | undefined): void {
  texture?.dispose();
}

// =============================================================================
// interaction (pointer/wheel -> refs)
// =============================================================================

interface DragSample {
  clientX: number;
  timestamp: number;
}

function attachInteractionHandlers(
  canvas: HTMLCanvasElement,
  refs: CarouselRuntimeRefs,
  configRef: ConfigRef,
): () => void {
  let previousSample: DragSample | null = null;
  let activePointerId: number | null = null;

  const markInteraction = () => {
    refs.lastInteractionAt = performance.now();
  };

  const updatePointerNDC = (clientX: number, clientY: number) => {
    const rect = canvas.getBoundingClientRect();
    refs.pointerNDC.x = ((clientX - rect.left) / rect.width) * 2 - 1;
    refs.pointerNDC.y = -((clientY - rect.top) / rect.height) * 2 + 1;
  };

  const handlePointerEnter = () => {
    refs.isPointerOverCanvas = true;
  };

  const endDrag = () => {
    if (activePointerId !== null && canvas.hasPointerCapture(activePointerId)) {
      canvas.releasePointerCapture(activePointerId);
    }
    activePointerId = null;
    previousSample = null;
    refs.isDragging = false;
    canvas.style.cursor = refs.hoveredCard ? 'pointer' : 'grab';
    markInteraction();
  };

  const handlePointerLeave = (event: PointerEvent) => {
    refs.isPointerOverCanvas = false;
    if (refs.isDragging && event.pointerId === activePointerId) {
      endDrag();
    }
  };

  const handlePointerDown = (event: PointerEvent) => {
    if (event.pointerType === 'mouse' && event.button !== 0) return;

    activePointerId = event.pointerId;
    canvas.setPointerCapture(event.pointerId);

    refs.isDragging = true;
    refs.scrollVelocity = 0;
    previousSample = { clientX: event.clientX, timestamp: performance.now() };

    updatePointerNDC(event.clientX, event.clientY);
    markInteraction();
    canvas.style.cursor = 'grabbing';
  };

  const handlePointerMove = (event: PointerEvent) => {
    updatePointerNDC(event.clientX, event.clientY);

    if (!refs.isDragging || event.pointerId !== activePointerId || !previousSample) {
      return;
    }

    const now = performance.now();
    const deltaX = event.clientX - previousSample.clientX;
    const deltaSeconds = Math.max((now - previousSample.timestamp) / 1000, 1 / 1000);

    const scrollDelta = -deltaX * configRef.current.dragSensitivity;
    refs.targetScrollX += scrollDelta;
    refs.scrollVelocity = scrollDelta / deltaSeconds;

    previousSample = { clientX: event.clientX, timestamp: now };
    markInteraction();
  };

  const handlePointerUp = (event: PointerEvent) => {
    if (event.pointerId !== activePointerId) return;
    endDrag();
  };

  const handleWheel = (event: WheelEvent) => {
    event.preventDefault();

    const scrollDelta = event.deltaY * WHEEL_SENSITIVITY;
    refs.targetScrollX += scrollDelta;
    refs.scrollVelocity = scrollDelta * 6;
    markInteraction();
  };

  canvas.addEventListener('pointerenter', handlePointerEnter);
  canvas.addEventListener('pointerleave', handlePointerLeave);
  canvas.addEventListener('pointerdown', handlePointerDown);
  canvas.addEventListener('pointermove', handlePointerMove);
  canvas.addEventListener('pointerup', handlePointerUp);
  canvas.addEventListener('pointercancel', handlePointerUp);
  canvas.addEventListener('wheel', handleWheel, { passive: false });
  canvas.style.cursor = 'grab';

  return function detachInteractionHandlers() {
    canvas.removeEventListener('pointerenter', handlePointerEnter);
    canvas.removeEventListener('pointerleave', handlePointerLeave);
    canvas.removeEventListener('pointerdown', handlePointerDown);
    canvas.removeEventListener('pointermove', handlePointerMove);
    canvas.removeEventListener('pointerup', handlePointerUp);
    canvas.removeEventListener('pointercancel', handlePointerUp);
    canvas.removeEventListener('wheel', handleWheel);
  };
}

// =============================================================================
// render loop
// =============================================================================

const grayscaleScratch = new THREE.Color();
const whiteScratch = new THREE.Color(0xffffff);

function resolveTargetScroll(refs: CarouselRuntimeRefs, config: CarouselConfig, dt: number): void {
  if (refs.isDragging) return;

  const hasMomentum = Math.abs(refs.scrollVelocity) > VELOCITY_EPSILON;

  if (hasMomentum) {
    refs.targetScrollX += refs.scrollVelocity * dt;
    refs.scrollVelocity = applyMomentumDecay(refs.scrollVelocity, config.momentum, dt);
    return;
  }

  const idleForMs = performance.now() - refs.lastInteractionAt;
  const isAutoplaying = idleForMs > AUTOPLAY_IDLE_DELAY_MS && config.autoplaySpeed !== 0;

  if (isAutoplaying) {
    refs.targetScrollX += config.autoplaySpeed * dt;
    return;
  }

  if (config.snap) {
    refs.targetScrollX = nearestSnapValue(refs.targetScrollX, config.spacing);
  }
}

function updateScrollPosition(refs: CarouselRuntimeRefs, config: CarouselConfig, dt: number): void {
  refs.currentScrollX = dampTowards(refs.currentScrollX, refs.targetScrollX, config.damping, dt);

  if (Math.abs(refs.currentScrollX) >= refs.cycleWidth / 2) {
    const cycles = Math.round(refs.currentScrollX / refs.cycleWidth);
    const shift = cycles * refs.cycleWidth;
    refs.currentScrollX -= shift;
    refs.targetScrollX -= shift;
  }

  for (const card of refs.cards) {
    const rawX = card.userData.baseX - refs.currentScrollX;
    card.position.x = wrapToWindow(rawX, refs.cycleWidth * 4);
  }
}

function setHoveredCard(refs: CarouselRuntimeRefs, next: CardMesh | null, config: CarouselConfig): void {
  if (refs.hoveredCard === next) return;

  if (refs.hoveredCard) {
    refs.hoveredCard.userData.hovered = false;
    refs.hoveredCard.userData.targetScale = 1;
  }

  if (next) {
    next.userData.hovered = true;
    next.userData.targetScale = config.hoverScale;
  }

  refs.hoveredCard = next;

  if (!refs.isDragging) {
    refs.renderer.domElement.style.cursor = next ? 'pointer' : 'grab';
  }
}

function updateHoverRaycast(refs: CarouselRuntimeRefs, config: CarouselConfig): void {
  if (refs.isDragging || !refs.isPointerOverCanvas) {
    setHoveredCard(refs, null, config);
    return;
  }

  refs.raycaster.setFromCamera(refs.pointerNDC, refs.camera);
  const intersections = refs.raycaster.intersectObjects(refs.cards, false);
  const nextHovered = (intersections[0]?.object as CardMesh | undefined) ?? null;

  setHoveredCard(refs, nextHovered, config);
}

function updateCardAnimations(refs: CarouselRuntimeRefs, config: CarouselConfig, dt: number): void {
  const grayAmount = clamp(config.hoverGrayscale, 0, 1);
  grayscaleScratch.setRGB(1 - grayAmount, 1 - grayAmount, 1 - grayAmount);
  const tintLerpFactor = dampFactor(HOVER_ANIMATION_DAMPING, dt);

  for (const card of refs.cards) {
    const data = card.userData;

    data.currentScale = dampTowards(data.currentScale, data.targetScale, HOVER_ANIMATION_DAMPING, dt);
    card.scale.setScalar(data.currentScale);

    const targetTint = data.hovered || grayAmount === 0 ? whiteScratch : grayscaleScratch;
    card.material.uniforms.tint.value.lerp(targetTint, tintLerpFactor);
  }
}

function updateCameraParallax(refs: CarouselRuntimeRefs, config: CarouselConfig, dt: number): void {
  const targetX = refs.isPointerOverCanvas ? refs.pointerNDC.x * config.cameraPan : 0;
  const targetY = refs.isPointerOverCanvas ? refs.pointerNDC.y * config.cameraPan * 0.5 : 0;

  refs.camera.position.x = dampTowards(refs.camera.position.x, targetX, CAMERA_PAN_DAMPING, dt);
  refs.camera.position.y = dampTowards(refs.camera.position.y, targetY, CAMERA_PAN_DAMPING, dt);
  refs.camera.lookAt(refs.camera.position.x, refs.camera.position.y, 0);
}

interface RenderLoopHandle {
  start: () => void;
  stop: () => void;
}

function createRenderLoop(refs: CarouselRuntimeRefs, configRef: ConfigRef): RenderLoopHandle {
  let previousTimestamp: number | null = null;

  function tick(timestamp: number) {
    if (refs.isDisposed || !refs.isRunning) {
      refs.frameId = null;
      return;
    }

    const config = configRef.current;

    const rawDeltaSeconds = previousTimestamp === null ? 0 : (timestamp - previousTimestamp) / 1000;
    previousTimestamp = timestamp;
    const dt = clamp(rawDeltaSeconds, 0, MAX_DELTA_SECONDS);

    resolveTargetScroll(refs, config, dt);
    updateScrollPosition(refs, config, dt);
    updateHoverRaycast(refs, config);
    updateCardAnimations(refs, config, dt);
    updateCameraParallax(refs, config, dt);

    refs.renderer.render(refs.scene, refs.camera);

    refs.frameId = requestAnimationFrame(tick);
  }

  return {
    start() {
      if (refs.frameId !== null || refs.isDisposed) return;
      refs.isRunning = true;
      previousTimestamp = null;
      refs.frameId = requestAnimationFrame(tick);
    },
    stop() {
      refs.isRunning = false;
      if (refs.frameId !== null) {
        cancelAnimationFrame(refs.frameId);
        refs.frameId = null;
      }
    },
  };
}

// =============================================================================
// useCarousel hook
// =============================================================================

function resolveConfig(props: CurveImageCarouselProps): CarouselConfig {
  const itemWidth = props.itemWidth ?? DEFAULT_ITEM_WIDTH;
  const gap = props.gap ?? DEFAULT_GAP;
  const itemHeight = props.itemHeight ?? DEFAULT_ITEM_HEIGHT;
  const requestedBorderRadius = props.borderRadius ?? DEFAULT_BORDER_RADIUS;

  return {
    itemWidth,
    itemHeight,
    borderRadius: Math.min(requestedBorderRadius, Math.min(itemWidth, itemHeight) / 2),
    gap,
    spacing: itemWidth * (1 + gap / 100),
    curveAmount: props.curveAmount ?? DEFAULT_CURVE_AMOUNT,
    repeatCount: props.repeatCount ?? DEFAULT_REPEAT_COUNT,
    dragSensitivity: props.dragSensitivity ?? DEFAULT_DRAG_SENSITIVITY,
    momentum: props.momentum ?? DEFAULT_MOMENTUM,
    damping: props.damping ?? DEFAULT_DAMPING,
    autoplaySpeed: props.autoplaySpeed ?? DEFAULT_AUTOPLAY_SPEED,
    snap: props.snap ?? DEFAULT_SNAP,
    cameraPan: props.cameraPan ?? DEFAULT_CAMERA_PAN,
    cameraFov: props.cameraFov ?? DEFAULT_CAMERA_FOV,
    hoverScale: props.hoverScale ?? DEFAULT_HOVER_SCALE,
    hoverGrayscale: props.hoverGrayscale ?? DEFAULT_HOVER_GRAYSCALE,
    pixelRatioCap: props.pixelRatioCap ?? DEFAULT_PIXEL_RATIO_CAP,
  };
}

function useCarousel(containerRef: RefObject<HTMLDivElement>, props: CurveImageCarouselProps): void {
  const configRef = useRef<CarouselConfig>(resolveConfig(props));
  configRef.current = resolveConfig(props);

  const runtimeRef = useRef<CarouselRuntimeRefs | null>(null);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;
    if (props.images.length === 0) return;

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, configRef.current.pixelRatioCap));
    renderer.setSize(container.clientWidth, container.clientHeight, false);
    renderer.domElement.style.display = 'block';
    renderer.domElement.style.width = '100%';
    renderer.domElement.style.height = '100%';
    container.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    const group = new THREE.Group();
    scene.add(group);

    const camera = new THREE.PerspectiveCamera(
      configRef.current.cameraFov,
      container.clientWidth / Math.max(container.clientHeight, 1),
      CAMERA_NEAR,
      CAMERA_FAR,
    );
    camera.position.set(0, 0, DEFAULT_CAMERA_DISTANCE);
    camera.lookAt(0, 0, 0);

    const raycaster = new THREE.Raycaster();

    const cycleWidth = configRef.current.spacing * props.images.length;

    const refs: CarouselRuntimeRefs = {
      renderer,
      scene,
      camera,
      group,
      raycaster,
      cards: [],
      currentScrollX: 0,
      targetScrollX: 0,
      scrollVelocity: 0,
      cycleWidth,
      isDragging: false,
      isPointerOverCanvas: false,
      pointerNDC: new THREE.Vector2(-10, -10),
      lastInteractionAt: performance.now(),
      hoveredCard: null,
      frameId: null,
      isRunning: false,
      isDisposed: false,
    };
    runtimeRef.current = refs;

    let cancelled = false;

    const totalMeshCount = props.images.length * configRef.current.repeatCount;
    const centerIndex = (totalMeshCount - 1) / 2;

    const sharedGeometry = buildCurvedPlaneGeometry(
      configRef.current.itemWidth,
      configRef.current.itemHeight,
    );

    for (let meshIndex = 0; meshIndex < totalMeshCount; meshIndex += 1) {
      const imageIndex = meshIndex % props.images.length;
      const image = props.images[imageIndex];
      const baseX = (meshIndex - centerIndex) * configRef.current.spacing;

      const material = buildCurveMaterial(
        configRef.current.curveAmount,
        configRef.current.itemWidth,
        configRef.current.itemHeight,
        configRef.current.borderRadius,
      );
      const mesh = new THREE.Mesh(sharedGeometry, material) as unknown as CardMesh;

      mesh.position.set(baseX, 0, 0);

      mesh.userData = {
        meshIndex,
        imageIndex,
        baseX,
        link: image.link,
        currentScale: 1,
        targetScale: 1,
        hovered: false,
      };

      group.add(mesh);
      refs.cards.push(mesh);

      loadCarouselTexture(image.src)
        .then((texture) => {
          if (cancelled || refs.isDisposed) {
            texture.dispose();
            return;
          }
          material.uniforms.map.value = texture;
        })
        .catch((error: unknown) => {
          console.error(`CurveImageCarousel: failed to load "${image.src}"`, error);
        });
    }

    const detachInteraction = attachInteractionHandlers(renderer.domElement, refs, configRef);
    const loop = createRenderLoop(refs, configRef);

    let pointerDownPosition: { x: number; y: number } | null = null;

    const handlePointerDownForClick = (event: PointerEvent) => {
      pointerDownPosition = { x: event.clientX, y: event.clientY };
    };
    const handlePointerUpForClick = (event: PointerEvent) => {
      if (!pointerDownPosition) return;
      const movedDistance = Math.hypot(
        event.clientX - pointerDownPosition.x,
        event.clientY - pointerDownPosition.y,
      );
      pointerDownPosition = null;

      if (movedDistance > DRAG_CLICK_THRESHOLD_PX) return;
      if (!refs.hoveredCard) return;

      const { imageIndex } = refs.hoveredCard.userData;
      props.onCardSelect?.(props.images[imageIndex], imageIndex);
    };
    renderer.domElement.addEventListener('pointerdown', handlePointerDownForClick);
    renderer.domElement.addEventListener('pointerup', handlePointerUpForClick);

    const resizeObserver = new ResizeObserver((entries) => {
      const entry = entries[0];
      if (!entry) return;
      const { width, height } = entry.contentRect;
      if (width === 0 || height === 0) return;

      renderer.setSize(width, height, false);
      camera.aspect = width / height;
      camera.updateProjectionMatrix();
    });
    resizeObserver.observe(container);

    const intersectionObserver = new IntersectionObserver(
      ([entry]) => {
        if (!entry) return;
        if (entry.isIntersecting) {
          loop.start();
        } else {
          loop.stop();
        }
      },
      { threshold: 0 },
    );
    intersectionObserver.observe(container);

    loop.start();

    return function disposeCarousel() {
      cancelled = true;
      refs.isDisposed = true;
      loop.stop();

      detachInteraction();
      renderer.domElement.removeEventListener('pointerdown', handlePointerDownForClick);
      renderer.domElement.removeEventListener('pointerup', handlePointerUpForClick);

      resizeObserver.disconnect();
      intersectionObserver.disconnect();

      refs.cards.forEach((card) => {
        disposeTexture(card.material.uniforms.map.value);
        card.material.dispose();
      });
      sharedGeometry.dispose();

      renderer.dispose();
      if (renderer.domElement.parentElement === container) {
        container.removeChild(renderer.domElement);
      }

      runtimeRef.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [containerRef, props.images, props.itemWidth, props.itemHeight, props.gap, props.curveAmount, props.repeatCount]);

  useEffect(() => {
    const refs = runtimeRef.current;
    if (!refs) return;
    refs.camera.fov = props.cameraFov ?? DEFAULT_CAMERA_FOV;
    refs.camera.updateProjectionMatrix();
  }, [props.cameraFov]);

  useEffect(() => {
    const refs = runtimeRef.current;
    if (!refs) return;
    refs.renderer.setPixelRatio(Math.min(window.devicePixelRatio, props.pixelRatioCap ?? DEFAULT_PIXEL_RATIO_CAP));
  }, [props.pixelRatioCap]);
}

// =============================================================================
// component
// =============================================================================

const visuallyHiddenStyle: CSSProperties = {
  position: 'absolute',
  width: 1,
  height: 1,
  overflow: 'hidden',
  clipPath: 'inset(50%)',
  whiteSpace: 'nowrap',
};

export function CurveImageCarousel(props: CurveImageCarouselProps) {
  const containerRef = useRef<HTMLDivElement>(null);

  useCarousel(containerRef, props);

  return (
    <div
      ref={containerRef}
      className={props.className}
      style={{
        position: 'relative',
        width: '100%',
        height: '100%',
        touchAction: 'none',
        ...props.style,
      }}
    >
      <ul style={visuallyHiddenStyle}>
        {props.images.map((image, index) => (
          <li key={image.src + index}>{image.alt ?? `Slide ${index + 1}`}</li>
        ))}
      </ul>
    </div>
  );
}
